const payload = $input.first().json ?? {};
const handoff = payload.edge_handoff ?? {};
const pull = handoff.pull ?? {};
const state = String(handoff.state ?? 'unavailable');
const lag = Number(handoff.sequence_lag ?? 0);
const age = Number(handoff.age_seconds ?? Number.POSITIVE_INFINITY);
const failure = String(pull.last_error ?? payload.error?.message ?? '');
const unhealthy = !handoff.configured || state === 'degraded' || state === 'stale' || state === 'unavailable' || pull.state === 'failed' || age > 1200;
const catchingUpTooLong = state === 'catching_up' && (lag > 0 || age > 600);
if (!unhealthy && !catchingUpTooLong) return [];
const signature = [state, lag, failure || 'no-error'].join('|');
const now = Date.now();
const store = $getWorkflowStaticData('global');
const previous = store.edgeSyncAlert ?? {};
if (previous.signature === signature && Number(previous.at ?? 0) > now - 30 * 60 * 1000) return [];
store.edgeSyncAlert = { signature, at: now };
const remote = handoff.remote_sequence ?? '-';
const local = handoff.sequence ?? '-';
const reason = failure || (state === 'catching_up' ? '同步仍有积压' : '同步状态异常');
return [{ json: { text: `【远端证据同步告警】状态：${state}；序列 ${local}/${remote}，积压 ${lag}；最近成功：${pull.last_success_at ?? '无'}；原因：${reason}` } }];
